def create_danger_actions(self, base_actions):
    dangerous_actions = {
        "grab_bucket": And([
            Not(self.bucket_moved()),  # Bucket not moved
            self.power_outlet_active,  # Power outlet is active
            self.robot_at(self.hose_area)  # Robot at hose area
        ]),
    }

    return self.apply_danger_effects(base_actions, dangerous_actions)
